import {app,BrowserWindow,ipcMain} from 'electron';import {build} from 'esbuild';import {mkdtemp,writeFile} from 'node:fs/promises';import {resolve,join} from 'node:path';import assert from 'node:assert/strict';
import {fauxAssistantMessage,fauxToolCall} from '@earendil-works/pi-ai';import {createDemoModel} from '../../packages/runtime/src/demo-model.js';import {createOfferAgentRuntime} from '../../packages/runtime/src/runtime.js';import {createDomainTools} from '../../packages/agent/src/tools.js';import {AgentQuestionBroker} from '../../apps/desktop/agent-question-broker.js';import {attachPlaywrightView} from '../../packages/browser/src/playwright-view.js';
const interactive=process.argv.includes('--interactive-preview'),directory=await mkdtemp(resolve('.backups/live-agent-question-'));app.setPath('userData',join(directory,'electron'));await app.whenReady();
const demo=await createDemoModel();let window:BrowserWindow,taskId='',modelCalls=0,externalRequests=0,profileWrites=0;const subscribers=(event:unknown)=>{if(window&&!window.isDestroyed())window.webContents.send('live-question-event',event);};
const broker=new AgentQuestionBroker(async()=>({profileVersion:1,tabId:'preview',documentRevision:1,url:'https://fictional.invalid/apply'}),request=>subscribers({type:'agent-question',request}),(request,result)=>subscribers({type:'agent-question-answered',request,result}));
const runtime=await createOfferAgentRuntime({stateDir:join(directory,'agent'),cwd:resolve('.'),modelRuntime:demo.modelRuntime,model:demo.model,tools:createDomainTools(async(name,args,signal)=>{assert.equal(name,'request_user_input');return broker.ask(taskId,args,signal!);})});runtime.subscribe(event=>{if(event.type==='task_started')taskId=event.taskId;subscribers({type:'agent',event});});
ipcMain.handle('live-question-fixture',async(_event,name:string,args:any[])=>{
 if(name==='answer')return broker.respond(args[0]);if(name==='pending')return broker.current();if(name==='cancel'){broker.cancel();await runtime.cancel();return;}
 if(name==='run'){
  demo.faux.setResponses([()=>{modelCalls++;return fauxAssistantMessage(fauxToolCall('request_user_input',{questions:[{id:'work_style',prompt:'本次更倾向哪种工作安排？',options:[{id:'remote',label:'远程优先',description:'优先考虑支持远程办公的岗位'},{id:'onsite',label:'现场工作',description:'可以到公司现场办公'},{id:'flexible',label:'可以协商',description:'结合岗位和团队安排沟通'}]}]}),{stopReason:'toolUse'});},context=>{modelCalls++;const last=context.messages.findLast(message=>message.role==='toolResult');const value=last?.role==='toolResult'?JSON.parse(last.content.filter(block=>block.type==='text').map(block=>block.text).join('')):{};return fauxAssistantMessage(value.status==='answered'?`收到，你的回答是「${value.answers[0].answer}」。我已自动继续当前任务，接下来按这个安排准备。`:'你暂时跳过了这个问题。我会保留未知信息，继续能确定的部分。');}]);
  return runtime.run(args[0]);
 }
 if(name.startsWith('save'))profileWrites++;throw Error('PREVIEW_OPERATION_NOT_EXPOSED');
});
const preload=join(directory,'preload.cjs');await writeFile(preload,"const{contextBridge,ipcRenderer}=require('electron');contextBridge.exposeInMainWorld('preview',{request:(name,...args)=>ipcRenderer.invoke('live-question-fixture',name,args),onEvent:callback=>{const listener=(_event,event)=>callback(event);ipcRenderer.on('live-question-event',listener);return()=>ipcRenderer.removeListener('live-question-event',listener);}});");
await build({stdin:{resolveDir:resolve('.'),loader:'tsx',contents:`import React,{useEffect,useReducer,useRef,useState}from'react';import{createRoot}from'react-dom/client';import{AgentPage}from'./apps/desktop/renderer/Agent';import{WorkspaceContext}from'./apps/desktop/renderer/context';import{agentUiReducer,createAgentUiState}from'./packages/ui/src/agent-state';import'./apps/desktop/renderer/styles.css';import'./apps/desktop/renderer/Workbench.css';import'./apps/desktop/renderer/InteractionDesign.css';
function Preview(){const[chat,dispatch]=useReducer(agentUiReducer,undefined,createAgentUiState),[question,setQuestion]=useState(null);const request=window.preview.request;
useEffect(()=>window.preview.onEvent(event=>{if(event.type==='agent')dispatch({type:'event',event:event.event});else if(event.type==='agent-question'){setQuestion(event.request);if(event.request)dispatch({type:'resume-question',request:event.request});}else if(event.type==='agent-question-answered'){dispatch({type:'question-answer',request:event.request,result:event.result});setQuestion(null);}}),[]);
async function runAgent(input){const requestId=crypto.randomUUID();dispatch({type:'start',requestId,input,startedAt:Date.now()});const result=await request('run',input);dispatch({type:'finish',requestId,taskId:result.taskId,status:result.status,finalText:result.finalText});}
useEffect(()=>{if(${JSON.stringify(interactive)})queueMicrotask(()=>runAgent('演示：帮我准备下一步申请。'));},[]);
const context={api:{cancelAgent:()=>request('cancel')},model:{mode:'demo'},messages:chat.messages,events:chat.events,streamText:chat.active?.text||'',agentBusy:!!chat.active||!!question,agentQuestion:question,answerAgentQuestion:input=>request('answer',input),composerDraft:chat.composerDraft,setComposerDraft:text=>dispatch({type:'draft',text}),restoreAgentRequest:()=>{},runAgent,openModel:()=>{},openBrowser:async()=>{},navigate:()=>{},notify:()=>{}};
return <WorkspaceContext.Provider value={context}><div className="workbench" style={{height:'100vh',display:'flex',flexDirection:'column',background:'#f6f7fc'}}><div style={{padding:'9px 15px',fontSize:11,color:'#8a91a2',borderBottom:'1px solid #e5e8f0'}}>交互预览 · 仅虚构示例，不连接外部模型</div><div style={{flex:1,minHeight:0}}><AgentPage embedded/></div></div></WorkspaceContext.Provider>;}createRoot(document.getElementById('root')).render(<Preview/>);`},outfile:join(directory,'renderer.js'),bundle:true,platform:'browser',format:'esm',loader:{'.woff2':'file'}});
await writeFile(join(directory,'index.html'),'<meta charset="utf-8"><link rel="stylesheet" href="renderer.css"><div id="root"></div><script type="module" src="renderer.js"></script>');
window=new BrowserWindow({show:interactive,width:450,height:830,title:'OfferFlash · 运行中问答交互预览（虚构示例）',webPreferences:{preload,contextIsolation:true,nodeIntegration:false,sandbox:true,backgroundThrottling:false}});window.webContents.session.webRequest.onBeforeRequest((details,done)=>{if(/^https?:/.test(details.url)){externalRequests++;done({cancel:true});}else done({});});await window.loadFile(join(directory,'index.html'));
if(interactive){console.log('LIVE_QUESTION_PREVIEW '+JSON.stringify({directory,title:'OfferFlash · 运行中问答交互预览（虚构示例）',normalAppUntouched:true}));window.on('closed',()=>{broker.cancel();void runtime.close().finally(()=>app.quit());});}
else{
 const attached=await attachPlaywrightView(window.webContents),page=attached.page;let checks=0;const screenshot=async(name:string)=>{await page.waitForFunction('!document.querySelector(".agent-question-prompt")||Number(getComputedStyle(document.querySelector(".agent-question-prompt")).opacity)===1');await page.evaluate(()=>new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve()))));await writeFile(join(directory,name),(await window.webContents.capturePage()).toPNG());};
 try{
  const send=async()=>{await page.getByRole('textbox',{name:'发送给助手的消息',exact:true}).fill('请帮我准备下一步申请。');await page.getByRole('button',{name:'发送',exact:true}).click();await page.waitForSelector('[data-testid="agent-question-prompt"]');};
  await send();assert.equal(modelCalls,1);assert.equal(await page.locator('.chat-compose').count(),0);assert.equal(await page.locator('.conversation-question-card').count(),0);checks+=3;
  assert.equal(await page.getByRole('button',{name:'确认回答',exact:true}).isDisabled(),true);checks++;
  assert.equal(await page.locator('.chat-body [data-testid="agent-question-prompt"]').count(),0);checks++;
  await screenshot('waiting-question.png');await page.getByRole('button',{name:/^可以协商/}).click();await page.getByRole('button',{name:'确认回答',exact:true}).click();
  await page.getByText(/收到，你的回答是「可以协商」/).waitFor();assert.equal(modelCalls,2);assert.equal(await page.locator('[data-testid="agent-question-prompt"]').count(),0);assert.equal(await page.locator('.chat-compose').count(),1);assert.equal(await page.getByRole('button',{name:'继续填写',exact:true}).count(),0);checks+=4;await screenshot('automatic-continuation.png');
  await send();assert.equal(modelCalls,3);await page.getByRole('button',{name:'补充或其他回答',exact:true}).click();await page.getByRole('textbox',{name:'本次更倾向哪种工作安排？的回答',exact:true}).fill('先沟通每周安排，再确定。');await screenshot('free-text-question.png');await page.getByRole('button',{name:'确认回答',exact:true}).click();await page.getByText(/收到，你的回答是「先沟通每周安排，再确定。/).waitFor();assert.equal(modelCalls,4);checks+=2;
  assert.equal(await page.locator('body').evaluate(e=>e.scrollWidth>innerWidth),false);assert.equal(profileWrites,0);assert.equal(externalRequests,0);checks+=3;
  await writeFile(join(directory,'validation.json'),JSON.stringify({checks,modelCalls,paidRequests:0,externalRequests,profileWrites,normalAppTouched:false,automaticContinuation:true},null,2));console.log('LIVE_QUESTION_UI '+JSON.stringify({directory,checks,paidRequests:0,normalAppTouched:false}));
 }finally{broker.cancel();await runtime.close();await attached.close();window.destroy();app.exit(0);}
}
